using System.IdentityModel.Tokens.Jwt;using MediDesk.Api.Authorization;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Catalog;using MediDesk.Common.Contracts.Finance;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace MediDesk.Api.Controllers{[ApiController][Route("api/schemes")]public sealed class SchemesController(ISchemeService s):ControllerBase{[HttpGet][Authorize(Policy=PermissionPolicies.SchemesView)]public async Task<ActionResult<PagedResponse<SchemeDto>>>Get([FromQuery]SchemeQuery q,CancellationToken ct)=>Ok(await s.GetPageAsync(q,ct));[HttpPost][Authorize(Policy=PermissionPolicies.SchemesAdd)]public async Task<ActionResult<SchemeDto>>Create(CreateSchemeRequest r,CancellationToken ct)=>Created("",await s.CreateAsync(r,Uid(),ct));[HttpPut("{id:long}")][Authorize(Policy=PermissionPolicies.SchemesEdit)]public async Task<IActionResult>Update(long id,UpdateSchemeRequest r,CancellationToken ct)=>Ok(await s.UpdateAsync(id,r,Uid(),ct));[HttpDelete("{id:long}")][Authorize(Policy=PermissionPolicies.SchemesDelete)]public async Task<IActionResult>Delete(long id,CancellationToken ct)=>await s.DeleteAsync(id,Uid(),ct)?NoContent():NotFound();long Uid()=>long.Parse(User.FindFirst(JwtRegisteredClaimNames.Sub)!.Value);}}

